    /// Emit a D-Bus signal
    EmitSignal,
    /// Property read
    PropertyGet,
    /// Property write
    PropertySet,
50→    /// Method invocation
    MethodCall,
    /// Snapshot creation
    CreateSnapshot,
    /// State import
    Import,
